var n=`0638-basbousa`;var a=`world-0638`;var t=`EG`;var s=`northern-africa`;var o=8;var r=65;var g={en:`Basbousa`,ua:`Басбуса`};var l={en:`Basbousa is a Egypt classic prepared with semolina flour, plain yogurt, baking powder, desiccated coconut. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Басбуса, страва кухні країни Єгипет зі складниками: семоліна, натуральний йогурт, розпушувач тіста, кокосова стружка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`semolina-flour`,350,`g`],[`plain-yogurt`,190,`g`],[`unsalted-butter`,100,`g`],[`white-granulated-sugar`,120,`g`],[`baking-powder`,8,`g`],[`desiccated-coconut`,65,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:5,i:[[`almond`,65,`g`]]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[]},{en:`Simmer sugar, water and lemon into a light syrup; pour the cool syrup onto the hot semolina cake so it soaks evenly.`,ua:`Зваріть легкий сироп із цукру, води й лимона; полийте ним гарячий манний пиріг для рівномірного просочення.`,t:[`reducing-sauce`],m:12,i:[[`water`,170,`ml`],[`white-granulated-sugar`,210,`g`],[`lemon-juice`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[]}];var d={slug:n,id:a,country:`EG`,region:s,servings:8,minutes:65,title:g,text:l,steps:u};export{t as country,d as default,a as id,r as minutes,s as region,o as servings,n as slug,u as steps,l as text,g as title};